// Command showroom reads one room through the API, the way a script or another service would.
package main

import (
	"cmp"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

type room struct {
	Name      string   `json:"name"`
	Building  string   `json:"building"`
	Capacity  int      `json:"capacity"`
	Amenities []string `json:"amenities"`
}

type problem struct {
	Status int    `json:"status"`
	Title  string `json:"title"`
}

func main() {
	base := cmp.Or(os.Getenv("ROOMBOOK_URL"), "http://localhost:8080")
	id := "1"
	if len(os.Args) > 1 {
		id = os.Args[1]
	}
	// The zero http.Client waits forever for a slow server. Always set a timeout.
	client := &http.Client{Timeout: 5 * time.Second}

	res, err := client.Get(base + "/v1/rooms/" + id)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Failed:", err)
		os.Exit(1)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		// A 4xx or 5xx isn't an error to Get. Roombook's errors are Problem Details, so read the title.
		var p problem
		json.NewDecoder(res.Body).Decode(&p)
		fmt.Fprintf(os.Stderr, "Failed: %d %s\n", p.Status, p.Title)
		os.Exit(1)
	}
	var r room
	if err := json.NewDecoder(res.Body).Decode(&r); err != nil {
		fmt.Fprintln(os.Stderr, "Failed:", err)
		os.Exit(1)
	}
	fmt.Printf("%s in %s seats %d: %s\n", r.Name, r.Building, r.Capacity, strings.Join(r.Amenities, ", "))
}

