package main

import (
	"cmp"
	"context"
	"fmt"
	"log"
	"os"

	"example.com/roombook/internal/roombookclient"
)

func main() {
	api, err := roombookclient.NewClientWithResponses(cmp.Or(os.Getenv("ROOMBOOK_URL"), "http://localhost:8080"))
	if err != nil {
		log.Fatal(err)
	}
	res, err := api.GetRoomWithResponse(context.Background(), 3)
	if err != nil {
		log.Fatal(err)
	}
	if res.JSON200 == nil {
		log.Fatalf("Failed: %s", res.Status())
	}
	fmt.Printf("%s in %s seats %d\n", res.JSON200.Name, res.JSON200.Building, res.JSON200.Capacity)
}
